(()=>{'use strict';
const D=window.CK_DATA,$=id=>document.getElementById(id),modal=$('modal'),body=$('modal-body'),world=$('world'),audio=CKAudio,reduced=matchMedia('(prefers-reduced-motion: reduce)');let phase='home',token=0,current=null,pendingItem=null,returnFocus=null,queuedTheme=null,toastTimer,typeTimer,typed='',pendingFocus=null,storageNotice=false;let local;try{local=localStorage;}catch(e){}const store=CKStore(D,local,message=>{if(!storageNotice){storageNotice=true;setTimeout(()=>toast(message),300);}});
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function url(v){try{const u=new URL(v,location.href);return ['https:','http:','mailto:','tel:'].includes(u.protocol)&&v?u.href:'';}catch(e){return '';}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function announce(text){$('announcer').textContent=text;}
function render(){const s=store.get(),theme=D.themes[s.theme];document.documentElement.dataset.theme=s.theme;$('location').textContent=theme.location;$('hero-title').innerHTML=theme.title;$('hero-copy').innerHTML=theme.copy;$('background').src=theme.background;$('background').alt=theme.alt;$('scene-label').textContent=theme.label;$('environment').textContent=theme.environment;$('scene-number').textContent=s.theme==='dark'?'01':'02';$('balance').textContent=s.balance.toLocaleString();$('unlock-count').textContent=`${s.unlocked.length} / 4 destinations discovered`;$('theme-btn').setAttribute('aria-label',`Switch to ${s.theme==='dark'?'Greed Island light':'Hunter’s Bar dark'} theme`);$('theme-btn').setAttribute('aria-pressed',String(s.theme==='light'));
 $('characters').innerHTML=Object.entries(theme.targets).map(([id,t])=>`<button class="hotspot ${id==='contact'?'phone':''}" data-section="${id}" style="left:${t.left}%" aria-label="${esc(t.name)}: ${D.sections[id].title}, ${s.unlocked.includes(id)?'unlocked':D.sections[id].price+' Hunter Credits'}"><img src="assets/${t.asset}.svg" alt=""><span class="hotspot-label">${esc(t.name)}<small>${D.sections[id].title.toUpperCase()} · ${s.unlocked.includes(id)?'UNLOCKED':D.sections[id].price+' HC'}</small></span></button>`).join('')+(s.theme==='dark'?'<button class="hotspot guide" id="kurapika" style="left:69%" aria-label="Kurapika: free exploration guide"><img src="assets/kurapika.svg" alt=""><span class="hotspot-label">Kurapika<small>YOUR GUIDE · FREE</small></span></button>':'');
 $('destination-grid').innerHTML=Object.entries(D.sections).map(([id,c],i)=>`<button class="destination-card" data-section="${id}"><span class="card-top"><span class="card-index">0${i+1}</span><span class="card-state">${s.unlocked.includes(id)?'✓ DISCOVERED':'⊙ '+c.price+' HC'}</span></span><h2>${c.title}</h2><span class="card-bottom"><span>${c.desc}</span><span>${c.icon}</span></span></button>`).join('');
 document.querySelectorAll('.desktop-nav button').forEach(b=>b.classList.toggle('active',b.dataset.section===current&&phase==='section'||b.hasAttribute('data-home')&&phase==='home'));updateSound();}
function updateSound(){const on=audio.enabled;$('sound-btn').setAttribute('aria-pressed',String(on));$('sound-btn').setAttribute('aria-label',on?'Mute sound':store.get().sound?'Resume sound':'Enable sound');$('sound-btn').innerHTML=on?'<svg viewBox="0 0 24 24"><path d="M11 5 6 9H3v6h3l5 4zM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>':'<svg viewBox="0 0 24 24"><path d="M11 5 6 9H3v6h3l5 4zM16 9l6 6m0-6-6 6"/></svg>';}
function camera(id){const target=world.querySelector(`[data-section="${id}"]`);if(!target)return;const vp=$('scene-viewport'),scale=innerWidth<600?1.65:1.8,x=target.offsetLeft+target.offsetWidth/2,y=target.offsetTop+target.offsetHeight*.42;const tx=vp.clientWidth/2-x*scale,ty=vp.clientHeight/2-y*scale;world.style.transform=`translate(${tx}px,${ty}px) scale(${scale})`;}
function restoreCamera(){world.style.transform='';}
function applyQueued(){if(queuedTheme){store.set('theme',queuedTheme);queuedTheme=null;render();}}
function openModal(kicker,content,klass=''){if(modal.open)modal.close();modal.className=klass;$('modal-kicker').textContent=kicker;body.innerHTML=content;modal.showModal();pendingFocus=body.querySelector('input,textarea,button,a')||$('close-modal');pendingFocus.focus();}
function close({focus=true}={}){token++;clearInterval(typeTimer);if(modal.open)modal.close();phase='home';current=null;pendingItem=null;restoreCamera();applyQueued();render();if(focus){if(returnFocus?.isConnected)returnFocus.focus();else $('credit-btn').focus();}}
function finishType(){clearInterval(typeTimer);const q=$('spoken-line');if(q)q.textContent=typed;const skip=$('skip-text');if(skip){skip.disabled=true;skip.textContent='Dialogue complete';}}
async function navigate(id,item=null){if(!D.sections[id])return;if(['zooming','dialogue','opening','returning'].includes(phase))return;returnFocus=document.activeElement;if(modal.open)modal.close();clearInterval(typeTimer);current=id;pendingItem=item;const n=++token;phase='zooming';const scene=$('scene-viewport'),bounds=scene.getBoundingClientRect();if(bounds.bottom<0||bounds.top>innerHeight)scene.scrollIntoView({block:'center',behavior:reduced.matches?'auto':'smooth'});camera(id);audio.play();await new Promise(resolve=>setTimeout(resolve,reduced.matches?0:720));if(n!==token)return;if(store.get().unlocked.includes(id)){applyQueued();openSection(id,item);return;}phase='dialogue';const t=D.themes[store.get().theme].targets[id],s=D.sections[id];typed=t.line;openModal('A NEW CHAPTER',`<h2 id="modal-title">A little curiosity?</h2><div class="dialogue-person"><img class="portrait" src="assets/${t.asset}.svg" alt="Original illustrative ${esc(t.name)} placeholder"><div><div class="dialogue-name">${esc(t.name)}</div><p class="dialogue-text" id="spoken-line"></p><button id="skip-text" class="text-btn">Skip text animation ↗</button></div></div><div class="dialogue-price"><span>Unlock ${s.title} · one time only</span><strong>${s.price} HC</strong></div><div class="actions"><button class="primary" id="confirm-unlock">Yes, discover ${s.title}</button><button class="secondary" id="cancel-unlock">Not now</button></div><p class="muted">Your balance: ${store.get().balance.toLocaleString()} HC. Fictional credits, no real money.</p>`,'small');announce(t.line);if(reduced.matches){finishType();}else{let i=0;typeTimer=setInterval(()=>{if(n!==token){clearInterval(typeTimer);return;}const el=$('spoken-line');if(el)el.textContent=typed.slice(0,++i);if(i>=typed.length)finishType();},18);}}
function sample(){return '<p class="sample-note">Editable sample content. These projects, biography, and proficiency values are illustrative placeholders, not verified personal achievements.</p>';}
function openSection(id,item){clearInterval(typeTimer);phase='section';current=id;const c=D.sections[id];let html=`<h2 id="modal-title">${c.title==='Projects'?'Ideas worth exploring.':c.title==='Skills'?'The craft behind the curiosity.':c.title==='About'?'A little about the creator.':'Every adventure starts with hello.'}</h2><p class="modal-sub">${id==='projects'?'A collection of small experiments and considered digital experiences.':id==='skills'?'A growing toolkit for bringing thoughtful ideas to life.':id==='about'?'The story, interests, and intentions behind this little world.':'Have an idea, a question, or a new journey in mind? Let’s talk.'}</p>`;
 if(id==='projects')html+=sample()+`<div class="project-grid">${D.projects.map(p=>`<article class="project-card" id="item-${p.id}"><div class="project-art" role="img" aria-label="Original typographic ${esc(p.title)} thumbnail"><span class="art-type">${esc(p.art)}</span></div><div class="project-info"><span class="eyebrow">${esc(p.status)}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="tags">${p.technologies.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${url(p.live)?`<a href="${esc(url(p.live))}" target="_blank" rel="noopener noreferrer">Live demo ↗</a>`:''}${url(p.source)?` <a href="${esc(url(p.source))}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}</div></article>`).join('')}</div>`;
 if(id==='skills')html+=sample()+`<div class="skill-grid">${D.skills.map(c=>`<article class="skill-category" id="item-${c.id}"><h3>${esc(c.title)}</h3>${c.items.map(([n,v])=>`<div class="skill-row"><div><span>${esc(n)}</span><small>${v}% · sample</small></div><div class="skill-track" role="meter" aria-label="${esc(n)} sample proficiency" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${v}"><span style="width:${v}%"></span></div></div>`).join('')}</article>`).join('')}</div>`;
 if(id==='about')html+=sample()+`<div class="about-layout" id="item-bio"><div class="profile-placeholder" role="img" aria-label="Profile image placeholder">C × K</div><div class="prose"><h3>${esc(D.profile.name)}</h3><p>${esc(D.profile.bio)}</p><h3>Outside the screen</h3><p>${D.profile.interests.map(esc).join(' · ')}</p><h3>Where I’m headed</h3><p>${esc(D.profile.goal)}</p><h3>Education & experience</h3><p>${esc(D.profile.education)}</p>${url(D.profile.resume)?`<a href="${esc(url(D.profile.resume))}">View résumé ↗</a>`:''}</div></div>`;
 if(id==='contact'){audio.play(store.get().theme==='dark'?'phone':'tap');html+=`<article class="contact-card" id="item-contact"><span class="eyebrow">${store.get().theme==='dark'?'BEATLE-07 / CONNECTION READY':'GREED ISLAND / CONTACT CARD 001'}</span><h3>Let’s make something good.</h3><p class="prose">${D.profile.email?`Email: <a href="mailto:${esc(D.profile.email)}">${esc(D.profile.email)}</a>`:'Contact details have not been supplied yet. You can prepare a message below; add the recipient in your email application.'}</p>${D.profile.phone?`<a href="tel:${esc(D.profile.phone)}">${esc(D.profile.phone)}</a>`:''}${D.profile.links.filter(l=>url(l.url)).map(l=>`<p><a href="${esc(url(l.url))}" target="_blank" rel="noopener noreferrer">${esc(l.label)} ↗</a></p>`).join('')}<form id="contact-form"><div class="contact-fields"><label>Your name<input name="name" autocomplete="name" required maxlength="100" placeholder="What should I call you?"></label><label>Subject<input name="subject" required maxlength="150" placeholder="A new adventure"></label><label>Your message<textarea name="message" required maxlength="3000" placeholder="Tell me a little about your idea…"></textarea></label></div><button class="primary" type="submit">Prepare email draft ↗</button><p class="muted">Opens your email app. No message is sent by this website.</p></form></article>`;}
 openModal(`PORTFOLIO / ${c.title.toUpperCase()} · UNLOCKED`,html);render();if(item){const el=$('item-'+item);if(el){el.classList.add('highlight');el.scrollIntoView({block:'center',behavior:reduced.matches?'auto':'smooth'});el.setAttribute('tabindex','-1');el.focus({preventScroll:true});}}}
function guide(first=false){returnFocus=document.activeElement;phase='guide';openModal('WELCOME, TRAVELER',`<h2 id="modal-title">Make yourself at home.</h2><p class="modal-sub">This is a portfolio you can explore — one character, one conversation, one little discovery at a time.</p><div class="intro-steps"><div class="intro-step"><span>01</span><div><strong>Choose a destination</strong>Click a character, use the navigation, or choose one of the four chapter cards.</div></div><div class="intro-step"><span>02</span><div><strong>A little fictional currency</strong>You begin with 1,000 Hunter Credits. Unlocking every chapter costs 750 HC. Confirm once, return freely.</div></div><div class="intro-step"><span>03</span><div><strong>Try another world</strong>The sun button takes you to Greed Island. Your discoveries travel with you.</div></div></div><p class="sample-note">An independent fan-inspired experience. Scene and character art are original stylized placeholders. No reference images or personal portfolio details were supplied. Credits have no monetary value and are saved only in this browser.</p><div class="actions"><button class="primary" id="start-exploring">${first?'Start exploring':'Back to the world'} ↗</button><button class="secondary" id="guide-credits">View my credits</button></div>`,'small');if(first)store.set('tutorial',true);}
function credits(){returnFocus=document.activeElement;phase='credits';const s=store.get();openModal('YOUR ADVENTURE',`<h2 id="modal-title">${s.balance.toLocaleString()} <em>HC</em></h2><p class="modal-sub">Hunter Credits are a playful way to discover this portfolio. No purchases. No real money. Every unlock is yours for this browser.</p><div class="ledger">${Object.entries(D.sections).map(([id,c])=>`<div><span>${c.title}</span><span>${s.unlocked.includes(id)?'✓ Unlocked':c.price+' HC'}</span></div>`).join('')}<div><strong>Starting balance</strong><strong>1,000 HC</strong></div></div><div class="actions"><button class="secondary" id="reset-progress">Reset my discoveries</button></div><p class="muted">Reset restores 1,000 HC and locks all four chapters. Theme and sound preferences stay as you chose them.</p>`,'small');}
const searchIndex=()=>[...Object.entries(D.sections).map(([id,c])=>({title:c.title,text:c.desc,section:id,item:null})),...D.projects.map(p=>({title:p.title,text:p.description+' '+p.technologies.join(' '),section:'projects',item:p.id})),...D.skills.map(c=>({title:c.title,text:c.items.map(i=>i[0]).join(' '),section:'skills',item:c.id})),{title:'The creator',text:D.profile.name+' '+D.profile.bio+' '+D.profile.interests.join(' '),section:'about',item:'bio'},{title:'Prepare an email',text:'contact email message conversation',section:'contact',item:'contact'}];
function search(){returnFocus=document.activeElement;phase='search';openModal('FIND YOUR NEXT CHAPTER','<h2 id="modal-title">A little looking around?</h2><label class="sr-only" for="search-input">Search projects, skills, and stories</label><input class="search-input" id="search-input" type="search" placeholder="Search projects, skills, stories…" autocomplete="off"><div class="search-results" id="search-results"></div><button class="text-btn" id="clear-search">Clear search</button>','search-dialog');results('');}
function results(query){const q=query.trim().toLowerCase(),items=searchIndex().filter(i=>!q||(i.title+' '+i.text).toLowerCase().includes(q)).slice(0,10);$('search-results').innerHTML=items.length?items.map(i=>`<button class="search-result" data-result="${i.section}" data-item="${i.item||''}"><span>${esc(i.title)}</span><small>${D.sections[i.section].title} · ${store.get().unlocked.includes(i.section)?'Unlocked':D.sections[i.section].price+' HC'}</small></button>`).join(''):'<p class="prose">No discoveries found. Try “design”, “journal”, or “contact”.</p>';}
function menu(){returnFocus=document.activeElement;phase='menu';openModal('YOUR DESTINATIONS','<h2 id="modal-title">Where to next?</h2><div class="menu-links"><button data-home>Home</button>'+Object.entries(D.sections).map(([id,c])=>`<button data-section="${id}">${c.title} <span class="muted">/ ${store.get().unlocked.includes(id)?'Discovered':c.price+' HC'}</span></button>`).join('')+'</div>','small');}
function theme(){const value=store.get().theme==='dark'?'light':'dark';if(['zooming','dialogue','opening'].includes(phase)){queuedTheme=value;toast('World change queued until this conversation ends.');return;}const scroll=modal.scrollTop;store.set('theme',value);render();if(phase==='section'){camera(current);modal.scrollTop=scroll;}audio.play();announce(value==='light'?'Entered Greed Island':'Entered the Hunter’s Bar');}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-home')){close();return;}if(b.dataset.section){navigate(b.dataset.section);return;}if(b.dataset.result){navigate(b.dataset.result,b.dataset.item||null);return;}
 switch(b.id){case'theme-btn':theme();break;case'sound-btn':if(audio.enabled){audio.mute();store.set('sound',false);}else{if(await audio.enable()){store.set('sound',true);audio.play();toast('Sound on — subtle original interaction tones.');}else toast('Sound could not start. You can still explore silently.');}updateSound();break;case'search-btn':if(!['zooming','dialogue'].includes(phase))search();break;case'menu-btn':if(!['zooming','dialogue'].includes(phase))menu();break;case'credit-btn':if(!['zooming','dialogue'].includes(phase))credits();break;case'guide-btn':case'footer-guide':case'kurapika':if(!['zooming','dialogue'].includes(phase))guide();break;case'close-modal':case'cancel-unlock':case'start-exploring':close();break;case'skip-text':finishType();break;case'guide-credits':credits();break;case'clear-search':$('search-input').value='';results('');$('search-input').focus();break;case'confirm-unlock':{if(phase!=='dialogue')return;b.disabled=true;const result=store.unlock(current);if(!result.ok){toast('Not enough Hunter Credits. No credits were spent.');b.disabled=false;return;}phase='opening';audio.play('unlock');announce(`${D.sections[current].title} unlocked. ${store.get().balance} Hunter Credits remain.`);const id=current,item=pendingItem;applyQueued();openSection(id,item);break;}case'reset-progress':openModal('START A NEW ADVENTURE','<h2 id="modal-title">Reset your discoveries?</h2><p class="modal-sub">Your four chapters will lock again and your balance will return to 1,000 HC. Your theme and sound preference will stay the same.</p><div class="actions"><button class="primary" id="confirm-reset">Yes, reset progress</button><button class="secondary" id="keep-progress">Keep my progress</button></div>','small');phase='reset';break;case'confirm-reset':store.reset();close();toast('A fresh adventure. 1,000 HC, four new discoveries.');break;case'keep-progress':credits();break;}});
document.addEventListener('input',e=>{if(e.target.id==='search-input')results(e.target.value);});document.addEventListener('submit',e=>{if(e.target.id==='contact-form'){e.preventDefault();const f=new FormData(e.target);location.href=`mailto:${encodeURIComponent(D.profile.email)}?subject=${encodeURIComponent(f.get('subject'))}&body=${encodeURIComponent('From: '+f.get('name')+'\n\n'+f.get('message'))}`;toast('Email draft requested. Complete and send it in your email app.');}});
modal.addEventListener('cancel',e=>{e.preventDefault();close();});modal.addEventListener('click',e=>{const r=modal.getBoundingClientRect();if(e.target===modal&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.open&&phase==='zooming')close();});window.addEventListener('resize',()=>{if(current&&['zooming','dialogue','section'].includes(phase))camera(current);});window.addEventListener('storage',e=>{if(e.key===D.storageKey){try{if(e.newValue&&store.sync(JSON.parse(e.newValue))){render();if(phase==='section'&&!store.get().unlocked.includes(current))close();toast('Progress updated from another tab.');}}catch(err){}}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&audio.enabled){audio.mute();updateSound();}});$('background').addEventListener('error',()=>toast('Scene artwork unavailable. Navigation still works below.'));render();if(!store.get().tutorial)setTimeout(()=>{if(phase==='home')guide(true);},400);
})();
